from ont_fast5_api.fast5_interface import get_fast5_file

logger = logging.getLogger('root')

def map_fast5_reads_to_reference_signal(fast5_dir: str, reference_signal: dict, results: str, f5c_eventalign_file: str, region: str, draw: bool):
    logger.info("Mapping fast5 reads from " + fast5_dir + " dir...")
    
    chr, positions = region.split(":")
    start, end = positions.split("-")
    start = int(start)
    end = int(end)

    df = pd.DataFrame()
    for chunk in pd.read_csv(f5c_eventalign_file, sep='\t', chunksize=50000):
        filtered_df = chunk.query('contig == @chr and position >= @start and position <= @end')
        df = pd.concat([df, filtered_df])
    logger.info("Number of rows after filtering: " + str(df.shape[0]))
    unique_reads = list(set(df['read_name']))
    logger.info("Number of unique reads after filtering: " + str(len(unique_reads)))
    
    fast5_files = []
    repeat_counts = []
    for subdir, dirs, files in os.walk(fast5_dir):
        for file in files:
            filepath = subdir + os.sep + file
            if filepath.endswith(".fast5"):
            #if filepath.endswith("5_strand.fast5"): # to speed up calculations
                fast5_files.append(filepath)
    for fast5_file in fast5_files:
        with get_fast5_file(fast5_file, mode="r") as f5:
            for read in f5.get_reads():
                raw_data = read.get_raw_data(scale=True)
                # poniżej wczytanie z wyników eventalign - do przeniesienia albo usunięcia
                if read.read_id not in unique_reads:
                    continue
                samples = df.query('read_name == @read.read_id')
                samples_string = ','.join(samples["samples"].values.tolist())
                samples_list = [float(i) for i in samples_string.split(',')] if samples_string != '' else []
                raw_data = samples_list

                repeat_count = estimate_repeat_count(read.read_id, raw_data, reference_signal, results, draw)
                repeat_counts.append(repeat_count)
    logger.info("Mapped " + str(len(repeat_counts)) + " reads from " + fast5_dir)
    print(repeat_counts)
    return repeat_counts

