def shouldStop(distance, distances):
    distances_values = [a_dict['distance'] for a_dict in distances]
    if len(distances_values) < 5:
        return False
    is_ascending = True
    for i in range(len(distances_values)-4,len(distances_values)-1):
        if distances_values[i] >= distances_values[i+1]: 
            is_ascending = False
            break
    return is_ascending



